Next, the Redux Toolkit reducer (cartSlice.js):
```javascript
// cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  subtotal: 0,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      state.items.push(action.payload);
      state.subtotal += action.payload.price;
    },
    removeItem(state, action) {
      state.items = state.items.filter((item) => item.id!== action.payload.id);
      state.subtotal -= action.payload.price;
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;
export default cartSlice.reducer;
```
Now the React component (Cart.js):
```javascript
// Cart.js
import React, { useEffect } from'react';
import { useSelector, useDispatch } from'react-redux';
import { Link } from'react-router-dom';
import { addToCart, removeFromCart } from './cartSlice';

function Cart() {
  const dispatch = useDispatch();
  const cart = useSelector((state) => state.cart);

  useEffect(() => {
    // fetch the cart from the server, e.g. using a backend API
    fetch('/api/cart')
     .then((response) => response.json())
     .then((data) => dispatch({ type: 'cart/cartUpdated', data }));
  }, []);

  return (
    <div>
      <h1>Shopping Cart</h1>
      <ul>
        {cart.items.map((item) => (
          <li key={item.id}>
            <Link to={`/product/${item.id}`}>
              {item.name} ({item.price})
            </Link>
            <button onClick={() => dispatch(removeItem(item))}>Remove</button>
          </li>
        ))}
      </ul>
      <p>Subtotal: ${cart.subtotal.toFixed(2)}</p>
      <Link to="/checkout">Checkout</Link>
    </div>
  );
}
```
